def run(j):
    out=os.path.join(A,j[0])
    if os.path.exists(out): return f'skip {j[0]}'
    r=subprocess.run([sys.executable,'-I',os.path.join(G,'gen.py'),out,j[1],'2K',j[2],str(j[3]),j[4]],capture_output=True,text=True)
    return (r.stdout+r.stderr).strip()[-300:]
only=set(sys.argv[1:])
with ThreadPoolExecutor(5) as ex:
    for res in ex.map(run,[j for j in J if not only or j[0] in only]): print(res,flush=True)
